 void main ()
 {

     vec2 umefx;
     umefx = acScreenNorm.st; 

     /////////////////////////

 	vec4 fragColor;
 	// How much is the price to rent your mother last night?  Fuck u stealer code
          vec2 uv = umefx;  // Normalisasi koordinat

          // Posisi default setiap sudut (diubah supaya orientasi benar)
          vec2 cornerTL = vec2(tl.x, tl.y); // Top Left
          vec2 cornerTR = vec2(tr.x, tr.y); // Top Right
          vec2 cornerBL = vec2(bl.x, bl.y); // Bottom Left
          vec2 cornerBR = vec2(br.x, br.y); // Bottom Right
          // vec2 cornerTL = vec2(0.0, 1.0); // Top Left
          // vec2 cornerTR = vec2(1.0, 1.0); // Top Right
          // vec2 cornerBL = vec2(0.0, 0.0); // Bottom Left
          // vec2 cornerBR = vec2(1.0, 0.0); // Bottom Right

          // Interpolasi bilinear
          vec2 top = mix(cornerTL, cornerTR, uv.x);  
          vec2 bottom = mix(cornerBL, cornerBR, uv.x);
          vec2 warpedUV = mix(bottom, top, uv.y);

          fragColor = texture2DCv(inputImg.texture, warpedUV);
          // fragColor = texture(iChannel0, warpedUV);

 	gl_FragColor = fragColor;
